float N = 16.;                                   // number of cells along height

#define T(X,Y) texelFetch(iChannel0, ivec2( S*I/N *R.y/R ) / 8  + ivec2(X,Y) , 3 ) // color at offset(X,Y) in cell(I)
                                                 // scaling may be changed with N
void mainImage( out vec4 O, vec2 u )
{   
    vec2 R = iResolution.xy,
         U = N*u/R.y, 
         I = floor(U),                           // cell ID
         F = (U-I)*2.-1.,                        // local coordinates in cell
         S = vec2(textureSize(iChannel0,0));     // texture size

    O = T(0,0);
    vec4 dX = T(1,0) - O,                        // gradient in R,G,B,A
         dY = T(0,1) - O;

    for( int i; i<4; i++ )
        O[i] += dot( F, vec2(dX[i],dY[i]) );     // linear color gradient around value

//  O *= smoothstep(1., 1.-3.*N/R.y, length(F) );// disc mask
}
